/**
 * The products source over a real products collection, on every configured
 * dialect.
 *
 * The unit suite proves the mapping against a stand-in for the collection
 * service. What only a database can answer is whether the queries the source
 * sends mean what it relies on there: a filter on a checkbox, a set of ids, a
 * comparison on the id for a cursor and a case-insensitive match on two text
 * columns, each generated by the adapter for its own dialect; and whether the
 * collection's field rules refuse a fraction before it reaches an integer
 * column that would round it.
 *
 * @module catalogue/products-source.integration.test
 */
import {
  definePlugin,
  NextlyError,
  type PluginContext,
} from "@nextlyhq/plugin-sdk";
import {
  createTestNextly,
  getConfiguredTestDialects,
  type TestDialect,
  type TestNextly,
} from "@nextlyhq/plugin-sdk/testing";
import { afterEach, describe, expect, it } from "vitest";

import { catalogueSourceContract } from "../testing/catalogue-source-contract";
import { runContractCases } from "../testing/contract-case";

import { productsCollection } from "./products-collection";
import { createProductsSource } from "./products-source";

function describeError(error: unknown): string {
  if (NextlyError.is(error)) {
    return `${String(error.code)} ${JSON.stringify(error.logContext ?? {})}`;
  }
  return error instanceof Error ? error.message : String(error);
}

describe.each(getConfiguredTestDialects())(
  "the products source (%s)",
  (dialect: TestDialect) => {
    let current: TestNextly | undefined;

    afterEach(async () => {
      await current?.destroy();
      current = undefined;
    });

    /** Boot with a plugin that contributes the products collection, and hand back its context. */
    async function boot(): Promise<PluginContext> {
      let captured: PluginContext | undefined;
      current = await createTestNextly({
        dialect,
        plugins: [
          definePlugin({
            name: "@test/commerce-products",
            version: "0.0.0",
            nextly: ">=0.0.0",
            contributes: { collections: [productsCollection()] },
            init(ctx) {
              captured = ctx;
            },
          }),
        ],
      });
      if (!captured) throw new Error("the test plugin's init did not run");
      return captured;
    }

    /** Store a product as the system, and give back its id. */
    async function seed(
      ctx: PluginContext,
      data: Record<string, unknown>
    ): Promise<string> {
      const { item } = await ctx.services.collections.createEntry(
        "products",
        data,
        { as: "system" }
      );
      return item.id;
    }

    function sourceFor(ctx: PluginContext) {
      return createProductsSource({
        collections: ctx.services.collections,
        slug: "products",
        currency: "USD",
      });
    }

    it("meets the catalogue contract", async () => {
      const ctx = await boot();
      // `sellable` is left out of every fixture, so the contract passing also
      // shows the field's default puts a product in the catalogue.
      const listed = await seed(ctx, {
        name: "Drill press",
        sku: "DP-1",
        price: 129_900,
        stockKind: "counted",
        stockCount: 4,
      });
      const onRequest = await seed(ctx, { name: "Custom rig" });
      const toOrder = await seed(ctx, {
        name: "Workbench",
        price: 45_000,
        stockKind: "to-order",
        maxPerLine: 20,
      });
      // More products than one page of two holds, so the listing case pages.
      const others: string[] = [];
      for (const name of ["Lathe", "Press brake", "Grinder"]) {
        others.push(await seed(ctx, { name, price: 1_000 }));
      }

      const cases = await catalogueSourceContract({
        currency: "USD",
        fixtures: {
          listed,
          onRequest,
          toOrder: { reference: toOrder, maxPerLine: 20 },
          // Not an id the collection could have issued, so an unknown
          // reference also proves a lookup by an id of another shape is
          // answered as unknown rather than failing in the database.
          unknown: "no-such-product",
          // Every product seeded, so the listing is held to the whole
          // catalogue rather than only the fixtures it names.
          catalogue: [listed, onRequest, toOrder, ...others],
          // The search reads the name and SKU, ignoring case: "drill" finds
          // the drill press and leaves out the custom rig.
          search: { query: "drill", finds: listed, skips: onRequest },
        },
        create: () => sourceFor(ctx),
      });
      const run = await runContractCases(cases);

      expect(
        run.failed.map(f => `${f.name}: ${describeError(f.error)}`)
      ).toEqual([]);
      expect(run.passed).toEqual(cases.map(c => c.name));
      // The listing and made-to-order cases exist only when the source offers
      // them, so their presence is checked rather than assumed.
      expect(run.passed).toEqual(
        expect.arrayContaining([
          expect.stringMatching(/^lists every item/),
          expect.stringMatching(/^reports an item sold to order/),
        ])
      );
    });

    it("leaves out a product that is not for sale, and keeps one whose sale flag was left to its default", async () => {
      const ctx = await boot();
      const forSale = await seed(ctx, { name: "Lathe", price: 1_000 });
      const withdrawn = await seed(ctx, {
        name: "Old lathe",
        price: 1_000,
        sellable: false,
      });
      const source = sourceFor(ctx);

      const found = await source.find({ references: [forSale, withdrawn] });
      expect(found.map(item => item.reference)).toEqual([forSale]);

      const listing = await source.list?.({ limit: 10 });
      expect(listing?.items.map(item => item.reference)).toEqual([forSale]);

      const priced = await source.price({
        currency: "USD",
        lines: [
          { reference: forSale, quantity: 1 },
          { reference: withdrawn, quantity: 1 },
        ],
      });
      expect(priced.map(line => line.found)).toEqual([true, false]);
    });

    it("narrows a listing by name or SKU, whatever the case, and pages through the matches", async () => {
      const ctx = await boot();
      const drill = await seed(ctx, { name: "Drill press", sku: "DP-1" });
      const lathe = await seed(ctx, { name: "Lathe", sku: "LT-9" });
      const brake = await seed(ctx, { name: "Press brake", sku: "PB-2" });
      const bench = await seed(ctx, { name: "Bench", sku: "PRESS-X" });
      await seed(ctx, { name: "Grinder" });
      const source = sourceFor(ctx);
      const list = source.list?.bind(source);
      if (!list) throw new Error("the products source lists");

      // One a page, so the cursor and the search are applied together.
      const matched: string[] = [];
      let cursor: string | null = null;
      do {
        const page = await list({ limit: 1, cursor, search: "PRESS" });
        matched.push(...page.items.map(item => item.reference));
        cursor = page.nextCursor;
      } while (cursor !== null && matched.length < 10);
      expect(matched).toHaveLength(3);
      expect(new Set(matched)).toEqual(new Set([drill, brake, bench]));

      const bySku = await list({ limit: 10, search: "lt-9" });
      expect(bySku.items.map(item => item.reference)).toEqual([lathe]);
    });

    it("refuses a price that is not a whole number when it is written", async () => {
      const ctx = await boot();

      const error = await ctx.services.collections
        .createEntry(
          "products",
          { name: "Drill press", price: 19.99 },
          { as: "system" }
        )
        .then(
          () => undefined,
          (caught: unknown) => caught
        );
      expect(NextlyError.isCode(error, "VALIDATION_ERROR")).toBe(true);
      expect(NextlyError.is(error) && error.publicData).toMatchObject({
        errors: [expect.objectContaining({ path: "price" })],
      });

      // The control: a whole price on the same collection is stored, so the
      // refusal is about the fraction and nothing else.
      const stored = await seed(ctx, { name: "Drill press", price: 1_999 });
      const [item] = await sourceFor(ctx).find({ references: [stored] });
      expect(item?.price).toEqual({
        kind: "listed",
        unitPrice: { amount: 1_999, currency: "USD" },
      });
    });
  }
);
